
from time import perf_counter

from app.services.base import GenerationResult, ModelProvider


class MockProvider(ModelProvider):

    async def generate(
        self,
        model: str,
        prompt: str,
    ) -> GenerationResult:

        start = perf_counter()

        response = (
            f"[Mock response] Received your prompt: {prompt.strip()}\n"
            "This response is generated by the local test adapter, "
            "not by an actual language model."
        )

        latency_ms = (perf_counter() - start) * 1000

        return GenerationResult(
            text=response,
            latency_ms=round(latency_ms, 3),
        )

    async def list_models(self) -> list:
        return [
            {
                "id": "mock-model",
                "name": "Mock Benchmark Model",
                "provider": "mock",
                "configured": True,
            }
        ]
